package webhookingest

// This file is hand-written. client.go beside it is generated by
// `cleat-gen plugin-client`, and scripts/check-generated-plugin-clients.sh
// compares only that file, so a regeneration leaves this one alone.

// DefaultEventType is the event_type the webhook-ingest plugin assigns an event
// whose sender set neither X-Github-Event nor X-Event-Type, and the one
// await_webhook claims when no EventType is given. It must equal the plugin's own
// default: the wait suspends on the signal "__evt:"+type, and the claim is keyed
// on an EXACT type, so a mismatch is a wait that never wakes. The plugin's tests
// assert the two agree.
const DefaultEventType = "webhook"

// AwaitWebhookWaiter is AwaitWebhook that can wait. It is the whole of what a
// workflow used to write by hand (a claim, a loop of suspends on the signal the
// claim's registration wakes, a re-claim after each wake):
//
//	got, err := webhookingest.AwaitWebhookWaiter.WaitFor(h, webhookingest.AwaitWebhookInput{
//		SourceID: id, EventType: "payment.confirmed", Keys: []string{orderID},
//	}, 5*time.Minute)
//
// err is non-nil when the claim fails AND when the window closes with no event;
// the second reads "wait_for_event: no event for webhook-ingest/await_webhook
// within <n>ms". That is how the engine reports it (a timeout is an error path
// there, not a flag), and the order-lifecycle example turns it into a refusal.
//
// The wake signal's name is kept in here so a caller does not spell it. The wait
// is durable and replay-safe: see PluginFunc.WaitFor and h.WaitForEvent.
var AwaitWebhookWaiter = AwaitWebhook.WithWake(func(in AwaitWebhookInput) []string {
	eventType := in.EventType
	if eventType == "" {
		eventType = DefaultEventType
	}
	return []string{"__evt:" + eventType}
})
